        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40601.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_COM_NM_onclick
 * @description btn_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        scwin.vMakId = js_market;
        if (scwin.vMakId === '1') {
            txb_MKT_NM.setValue("유가증권시장");
        } else if (scwin.vMakId === '2') {
            txb_MKT_NM.setValue("코스닥증권시장");
        } else if (scwin.vMakId === '6') {
            txb_MKT_NM.setValue("코넥스증권시장");
        } else {
            txb_MKT_NM.setValue("-");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40601.btn_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (cmb_LIST_CERT_USE_TP_CD.BindColVal !== "") {
            for (i = 1; i <= dts_useContn.getRowCount(); i++) {
                if (dts_useContn.getCellData(i, "LIST_CERT_USE_TP_CD") === cmb_LIST_CERT_USE_TP_CD.getValue()) {
                    await $c.win.alert("동일한 용도구분은 추가하실수 없습니다.");
                    return;
                }
            }
            dts_useContn.insertRow();
            dts_useContn.setCellData(dts_useContn.getRowPosition(), "LIST_CERT_USE_TP_CD", cmb_LIST_CERT_USE_TP_CD.getValue());
            dts_useContn.setCellData(dts_useContn.getRowPosition(), "LIST_CERT_USE_CONTN", $c.stf.getComboTextValue(cmb_LIST_CERT_USE_TP_CD));
        } else {
            return;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40601.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        if (scwin.notiId === "input") {
            dts_useContn.removeRow(dts_useContn.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40601.btn_linedelete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setMainHeader
 * @description set Main Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setMainHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_certificateApprove",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_certificateApprove=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_certificateApprove.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_useContn",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_useContn=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    01443 - 상장증명서용도구분코드
     */
    const arrCid = [{
        cid: "LIST_CERT_USE_TP_CD",
        cnm: "cmb_LIST_CERT_USE_TP_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                if (dts_Cod.getCellData(j, "VALUE") !== '99') {
                    // 담당자요구로 기타 삭제(2008.11.12)
                    strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/CertificateApprove.do",
        ref : "dts_readCertificateApprove,dts_useContn",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_COM_NM.getValue() === "") {
        await $c.win.alert("[회사코드/명]를 선택해주세요.");
        txb_COM_NM.focus();
        return;
    }
    if (rdo_LIST_CERT_TP_CD.getValue() === "") {
        await $c.win.alert("[상장증명서구분]을 선택해주세요.");
        rdo_LIST_CERT_TP_CD.focus();
        return;
    }
    if (rdo_KORENG_TP_CD.getValue() === "") {
        await $c.win.alert("[한글영문구분]을 선택해주세요.");
        rdo_KORENG_TP_CD.focus();
        return;
    }
    if (dts_useContn.getRowCount() === 0) {
        await $c.win.alert("[용도구분]을 1개 이상 추가해주세요.");
        cmb_LIST_CERT_USE_TP_CD.focus();
        return;
    }
    let rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn === 1) {
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "ISUR_CD", txb_ISUR_CD.getValue());
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "MKT_ID", scwin.vMakId);
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "CERT_APPL_USR_ID", js_emp_no);
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "LIST_CERT_PROCS_STAT_CD", "1"); // 등록시 접수 '1'로 세팅

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/CertificateApprove.do",
            ref : "dts_certificateApprove,dts_useContn",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @param {String} listCertApplId listCertApplId
 * @param {*} bycertSeq bycertSeq
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} korengTpCd korengTpCd
 * @param {String} listCertTpCd listCertTpCd
 * @param {*} listNo listNo
 * @param {String} stkcertDelistDd stkcertDelistDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function(listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, listNo, stkcertDelistDd) {
    let pdf_rptname;
    let dataUrl = "/CertificateApprove.do?method=searchListCertificate&outputMessageId=LISTCERT_REPORT_INOUT" + "&SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq;
    // 상장증명서
    if (listCertTpCd === "1") {
        if (ldMktTpCd === "1") {
            // 유가증권시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=1";
                pdf_rptname = "RLDSTF10005";
            } else {
                // 영문증명서
                dataUrl = dataUrl + "&reportDiv=2";
                pdf_rptname = "RLDSTF10006";
            }
        } else if (ldMktTpCd === "2") {
            // 코스닥시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=3";
                pdf_rptname = "RLDSTF10013";
            } else {
                // 영문증명서
                dataUrl = dataUrl + "&reportDiv=4";
                pdf_rptname = "RLDSTF10014";
            }
        } else {
            // 코넥스시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=3";
                pdf_rptname = "RLDSTF10037";
            } else {
                // 영문증명서
                dataUrl = dataUrl + "&reportDiv=4";
                pdf_rptname = "RLDSTF10038";
            }
        }
    } else {
        // 상장폐지증명서

        if (ldMktTpCd === "1") {
            // 유가

            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10009";
                } else {
                    pdf_rptname = "RLDSTF10016";
                }
            } else {
                // 영문증명서
                dataUrl = dataUrl + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10010";
                } else {
                    pdf_rptname = "RLDSTF10019";
                }
            }
        } else if (ldMktTpCd === "2") {
            // 코스닥

            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10011";
                } else {
                    pdf_rptname = "RLDSTF10018";
                }
            } else {
                // 영문증명서
                dataUrl = dataUrl + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10012";
                } else {
                    pdf_rptname = "RLDSTF10017";
                }
            }
        } else {
            // 코넥스
            if (korengTpCd === "1") {
                // 한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10011";
                } else {
                    pdf_rptname = "RLDSTF10018";
                }
            } else {
                // 영문증명서
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10012";
                } else {
                    pdf_rptname = "RLDSTF10017";
                }
            }
        }
    }
    const sbmOptions = {
        id : "sbm_dts_Report",
        action : "&reportDiv=6",
        ref : "",
        target : "dts_Report=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // set data report --> target (DB컬럼명과 Report 컬럼명이 다름)
    const dtsFormatArr = ["certSeq:CERT_SEQ:STRING", "comNm:COM_NM:STRING", "listCmstkShrs:LIST_CMSTK_SHRS:DECIMAL", "listPrefstkShrs:LIST_PREFSTK_SHRS:DECIMAL", "parval:PARVAL:STRING", "cap:CAP:DECIMAL", "currIsoCd:CURR_ISO_CD:STRING", "ldMktTpCd:LD_MKT_TP_CD:STRING", "listDd:LIST_DD:STRING", "listCertUseContn:LIST_CERT_USE_CONTN:STRING", "today:TODAY:STRING", "ceoNm:CEO_NM:STRING", "indNm:IND_NM:STRING", "listNo:LIST_NO:DECIMAL", "stkcertDelistDd:STKCERT_DELIST_DD:STRING"];

    // set dataFormat
    let dataFormatArr = [];
    if (korengTpCd === "1") {
        // 한글증명서
        dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEx3", "STKCERT_DELIST_DD:FormatDateEx3", "TODAY:FormatDateEx3"];
    } else {
        if (listCertTpCd === "1" && ldMktTpCd === "1") {
            // 상장증명서 && 유가 && 영문증명서
            dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEngEx1", "STKCERT_DELIST_DD:FormatDateEngEx1", "TODAY:FormatDateEngEx1"]; // YYYYMMDD --> YYYY. MM. DD

        } else {
            dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEngEx3", "STKCERT_DELIST_DD:FormatDateEngEx3", "TODAY:FormatDateEngEx3"]; // MMDDYYYY --> MM.DD.YYYY

        }
    }
    const jsonData = $c.rpt.fn_make_dtsToJson3_wdf(dtsFormatArr, dts_Report, dataFormatArr);

    //        alert(JSON.stringify(jsonData));
    const userParam = [{
        uid: "jsonData",
        unm: jsonData
    }];

    // PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name approve
 * @description approve 처리
 * @returns {void}
 * @hidden N
 */
scwin.approve = function() {
    let rtn = confirm('증명서발급을 승인처리 하시겠습니까?');
    if (rtn === 1) {
        let vStatCd = '9'; // 승인
        scwin.trs(vStatCd);
    }
};

/**
 * @method
 * @name reject
 * @description reject 처리
 * @returns {void}
 * @hidden N
 */
scwin.reject = function() {
    let rtn = confirm('증명서발급을 거부처리 하시겠습니까?');
    if (rtn === 1) {
        let vStatCd = '5'; // 거부
        scwin.trs(vStatCd);
    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {String} gStatCd gStatCd
 * @returns {void}
 * @hidden N
 */
scwin.trs = function(gStatCd) {
    dts_readCertificateApprove.setCellData(1, "LIST_CERT_PROCS_STAT_CD", gStatCd);
    dts_readCertificateApprove.setCellData(1, "ISU_CHRG_EMP_NO", js_emp_no);
    const url = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=approveCertificate";
    trs_Update.Action = encodeURI(url);
    trs_Update.KeyValue = "JSP(I:pInput=dts_readCertificateApprove)";
    trs_Update.Post();
};

/**
 * @method
