 * @param {*} listNo listNo
 * @param {String} stkcertDelistDd stkcertDelistDd
 * @returns {void}
 * @hidden N
 */
scwin.printOld = function(listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, listNo, stkcertDelistDd) {
    let rexName;
    const dataType = "XML";
    let dataLocation = "";
    const dataXPath = "main/rpt1";
    const svrGubun = js_svrGubun; // 서버구분(session.js정보)

    // 상장증명서
    if (listCertTpCd === "1") {
        if (ldMktTpCd === "1") {
            // 유가증권시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=1";
                rexName = "RLDFIL00005";
