                // 영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=2";
                rexName = "RLDFIL00006";
            }
        } else if (ldMktTpCd === "2") {
            // 코스닥시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                rexName = "RLDFIL00013";
            } else {
                // 영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                rexName = "RLDFIL00014";
            }
        } else {
            // 코넥스시장
            if (korengTpCd === "1") {
                // 한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                rexName = "RLDFIL00037";
            } else {
                // 영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                rexName = "RLDFIL00038";
            }
        }
    } else {
        // 상장폐지증명서

        if (ldMktTpCd === "1") {
            // 유가

            if (korengTpCd === "1") {
                // 한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00009";
