                dataLocation = "/CertificateApprove.do?SCREN_ID=" + "ULDSTF40601.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00012";
                } else {
                    rexName = "RLDFIL00017";
                }
            }
        } else {
            // 코넥스
            if (korengTpCd === "1") {
